use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::env;
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::atomic::{AtomicU64, Ordering};

static REQUESTS: AtomicU64 = AtomicU64::new(0);
static DENIED: AtomicU64 = AtomicU64::new(0);
#[derive(Deserialize, Serialize, Clone)] struct Point { key: String, latitude: f64, longitude: f64 }
#[derive(Deserialize)] struct CorridorRequest { corridor: Vec<Point>, assets: Vec<Point>, buffer_meters: f64 }
#[derive(Serialize)] struct CorridorResult { inspected_assets: usize, nearby_asset_keys: Vec<String>, method: &'static str, decision_boundary: &'static str }
#[derive(Deserialize)] struct ExposureEvent { key: String, layer: String, latitude: f64, longitude: f64 }
#[derive(Deserialize)] struct ExposureRequest { assets: Vec<Point>, events: Vec<ExposureEvent>, max_distance_meters: f64 }
#[derive(Serialize)] struct ExposureResult { inspected_assets: usize, inspected_events: usize, nearby_event_counts: BTreeMap<String, usize>, method: &'static str, decision_boundary: &'static str }
fn valid(p:&Point)->bool { !p.key.trim().is_empty() && p.key.len()<=96 && p.latitude.is_finite() && p.longitude.is_finite() && (-90.0..=90.0).contains(&p.latitude) && (-180.0..=180.0).contains(&p.longitude) }
fn distance(a:&Point,b:&Point)->f64 { let r=6_371_000.0_f64; let dlat=(b.latitude-a.latitude).to_radians();let dlon=(b.longitude-a.longitude).to_radians();let x=(dlat/2.0).sin().powi(2)+a.latitude.to_radians().cos()*b.latitude.to_radians().cos()*(dlon/2.0).sin().powi(2);2.0*r*x.sqrt().asin() }
fn http(stream:&mut TcpStream,status:&str,content_type:&str,body:&str){let response=format!("HTTP/1.1 {}\r\nContent-Type: {}\r\nContent-Length: {}\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n{}",status,content_type,body.len(),body);let _=stream.write_all(response.as_bytes());}
fn parse(stream:&mut TcpStream)->Option<(String,String,String,String)> { let mut raw=Vec::new(); if stream.read_to_end(&mut raw).is_err(){return None};let text=String::from_utf8(raw).ok()?;let (head,body)=text.split_once("\r\n\r\n")?;let mut lines=head.lines();let first=lines.next()?.split_whitespace().collect::<Vec<_>>();if first.len()!=3{return None};let token=lines.find_map(|line|line.strip_prefix("X-Portfolio-Engine-Key:").map(|v|v.trim().to_string())).unwrap_or_default();Some((first[0].to_string(),first[1].to_string(),token,body.to_string())) }
fn require_key(received:&str,expected:&str)->bool { received.len()==expected.len() && received.as_bytes().iter().zip(expected.as_bytes()).fold(0u8,|acc,(a,b)|acc|(a^b))==0 }
fn handle(mut stream:TcpStream,secret:&str){let Some((method,path,token,body))=parse(&mut stream) else {http(&mut stream,"400 Bad Request","text/plain","invalid request");return};if method=="GET"&&path=="/health"{http(&mut stream,"200 OK","application/json",r#"{"status":"healthy","service":"portfolio-spatial-engine"}"#);return}if method=="GET"&&path=="/ready"{http(&mut stream,"200 OK","application/json",r#"{"status":"ready"}"#);return}if method=="GET"&&path=="/metrics"{http(&mut stream,"200 OK","text/plain",&format!("portfolio_spatial_requests_total {}\nportfolio_spatial_denied_total {}\n",REQUESTS.load(Ordering::Relaxed),DENIED.load(Ordering::Relaxed)));return}if method!="POST"{http(&mut stream,"405 Method Not Allowed","text/plain","method not allowed");return}if !require_key(&token,secret){DENIED.fetch_add(1,Ordering::Relaxed);http(&mut stream,"401 Unauthorized","application/json",r#"{"error":"engine authorization failed"}"#);return}REQUESTS.fetch_add(1,Ordering::Relaxed);if path=="/v1/corridor/inspect"{let Ok(input)=serde_json::from_str::<CorridorRequest>(&body) else {http(&mut stream,"400 Bad Request","application/json",r#"{"error":"invalid corridor request"}"#);return};if input.corridor.len()<2||input.corridor.len()>5000||input.assets.len()>10000||!input.corridor.iter().all(valid)||!input.assets.iter().all(valid)||!input.buffer_meters.is_finite()||input.buffer_meters<0.0||input.buffer_meters>100_000.0{http(&mut stream,"422 Unprocessable Content","application/json",r#"{"error":"bounded WGS84 inputs required"}"#);return};let nearby=input.assets.iter().filter(|asset|input.corridor.iter().any(|point|distance(point,asset)<=input.buffer_meters)).map(|asset|asset.key.clone()).collect();let out=CorridorResult{inspected_assets:input.assets.len(),nearby_asset_keys:nearby,method:"haversine point-to-corridor-vertex proximity",decision_boundary:"Operational spatial proximity only; no property, access, acquisition, safety, or legal decision."};http(&mut stream,"200 OK","application/json",&serde_json::to_string(&out).unwrap());return}if path=="/v1/exposure/summarize"{let Ok(input)=serde_json::from_str::<ExposureRequest>(&body) else {http(&mut stream,"400 Bad Request","application/json",r#"{"error":"invalid exposure request"}"#);return};if input.assets.len()>10000||input.events.len()>20000||!input.assets.iter().all(valid)||input.events.iter().any(|e|e.key.trim().is_empty()||e.layer.trim().is_empty()||!e.latitude.is_finite()||!e.longitude.is_finite()||e.latitude < -90.0||e.latitude>90.0||e.longitude < -180.0||e.longitude>180.0)||!input.max_distance_meters.is_finite()||input.max_distance_meters<0.0||input.max_distance_meters>500_000.0{http(&mut stream,"422 Unprocessable Content","application/json",r#"{"error":"bounded WGS84 inputs required"}"#);return};let mut counts=BTreeMap::new();for event in input.events{let event_point=Point{key:event.key.clone(),latitude:event.latitude,longitude:event.longitude};if input.assets.iter().any(|asset|distance(asset,&event_point)<=input.max_distance_meters){*counts.entry(event.layer).or_insert(0)+=1}}let out=ExposureResult{inspected_assets:input.assets.len(),inspected_events:counts.values().sum(),nearby_event_counts:counts,method:"haversine asset-event proximity aggregation",decision_boundary:"Attributed contextual exposure summary only; no underwriting, claims, emergency, safety, or investment decision."};http(&mut stream,"200 OK","application/json",&serde_json::to_string(&out).unwrap());return}http(&mut stream,"404 Not Found","application/json",r#"{"error":"not found"}"#)}
fn main(){let secret=env::var("PORTFOLIO_SPATIAL_ENGINE_SECRET").unwrap_or_else(|_|panic!("PORTFOLIO_SPATIAL_ENGINE_SECRET is required"));if secret.len()<32{panic!("PORTFOLIO_SPATIAL_ENGINE_SECRET must be at least 32 characters")};let port=env::var("PORT").unwrap_or_else(|_|"8097".to_string());let listener=TcpListener::bind(format!("0.0.0.0:{port}")).expect("bind failed");for stream in listener.incoming(){if let Ok(stream)=stream{handle(stream,&secret)}}}
